import{b as r,O as o,g as d,j as e}from"./chunks/framework.DcaUmd3X.js";const q=JSON.parse('{"title":"测试全流程","description":"","frontmatter":{},"headers":[],"relativePath":"testing/execution/test-process/index.md","filePath":"测试理论与实践/2.测试执行过程/04.测试全流程.md","lastUpdated":1782289777000}'),a={name:"testing/execution/test-process/index.md"};function n(s,t,l,i,h,g){return o(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="测试全流程" tabindex="-1">测试全流程 <a class="header-anchor" href="#测试全流程" aria-label="Permalink to &quot;测试全流程&quot;">​</a></h1><blockquote><p>从接到需求到交付测试报告，一张图看清整个测试工作链路——计划、设计、执行、报告，每步踩在哪、产出什么。</p></blockquote><h2 id="全景图-测试工作的四个阶段" tabindex="-1">全景图：测试工作的四个阶段 <a class="header-anchor" href="#全景图-测试工作的四个阶段" aria-label="Permalink to &quot;全景图：测试工作的四个阶段&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>测试计划 ──→ 测试设计与实现 ──→ 测试执行 ──→ 测试评估与报告</span></span>
<span class="line"><span>(定方向)      (写用例)         (找bug)       (给结论)</span></span></code></pre></div><p>这四个阶段构成了测试工作的主干。下面逐一拆解。</p><h2 id="测试计划-开工之前先想清楚" tabindex="-1">测试计划：开工之前先想清楚 <a class="header-anchor" href="#测试计划-开工之前先想清楚" aria-label="Permalink to &quot;测试计划：开工之前先想清楚&quot;">​</a></h2><p>测试计划就是回答一个问题：<strong>这个项目，你打算怎么测？</strong></p><p>根据 IEEE 829 标准，一份完整的测试计划包含 9 大要素（详见<a href="/testing/appendix/test-plan.html">附录：测试计划</a>）：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>要素</th><th>回答的问题</th><th>一句话说明</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>测试计划标识符</strong></td><td>这是哪份计划？</td><td>唯一编号，方便追溯和引用</td></tr><tr><td style="text-align:center;">2</td><td><strong>引言/背景</strong></td><td>为什么要测？</td><td>项目背景、测试目标和范围概述</td></tr><tr><td style="text-align:center;">3</td><td><strong>测试项</strong></td><td>测什么、不测什么？</td><td>列出包含和不包含的功能模块</td></tr><tr><td style="text-align:center;">4</td><td><strong>测试策略</strong></td><td>怎么测？测多深？</td><td>每类测试用什么方法、覆盖到什么程度</td></tr><tr><td style="text-align:center;">5</td><td><strong>测试环境</strong></td><td>在哪测？</td><td>硬件、软件、数据、工具的配置清单</td></tr><tr><td style="text-align:center;">6</td><td><strong>进度安排</strong></td><td>什么时候做什么？</td><td>各阶段的时间、人员、产出物</td></tr><tr><td style="text-align:center;">7</td><td><strong>风险与应对</strong></td><td>可能出什么幺蛾子？</td><td>识别风险、评估概率和影响、制定应对方案</td></tr><tr><td style="text-align:center;">8</td><td><strong>暂停与恢复标准</strong></td><td>什么时候喊停、什么时候继续？</td><td>定义测试中断和恢复的条件</td></tr><tr><td style="text-align:center;">9</td><td><strong>交付物</strong></td><td>测完交什么？</td><td>测试结束后需要产出的文档和产物</td></tr></tbody></table><blockquote><p>9 个要素里，<strong>测试项</strong>（测什么）和<strong>测试策略</strong>（怎么测）是最核心的两块，其余都是围绕它们服务的。完整模板和示例见<a href="/testing/appendix/test-plan.html">附录：测试计划</a>。</p></blockquote><h3 id="暂停-恢复标准与退出标准" tabindex="-1">暂停 / 恢复标准与退出标准 <a class="header-anchor" href="#暂停-恢复标准与退出标准" aria-label="Permalink to &quot;暂停 / 恢复标准与退出标准&quot;">​</a></h3><p>IEEE 829 中第 8 要素是<strong>暂停与恢复标准</strong>——定义什么情况下测试要中断、满足什么条件才能恢复（详见<a href="/testing/execution/testing/appendix/test-plan.html#8-暂停与恢复标准">附录：测试计划 #8</a>）：</p><table tabindex="0"><thead><tr><th>暂停条件</th><th>恢复条件</th></tr></thead><tbody><tr><td>冒烟测试不通过（核心流程阻塞）</td><td>开发修复后重新提测，冒烟通过</td></tr><tr><td>致命 Bug 导致 30% 以上用例无法执行</td><td>Bug 修复、该模块恢复可用</td></tr><tr><td>测试环境宕机超过 4 小时</td><td>环境恢复且通过可用性验证</td></tr></tbody></table><p>除了&quot;什么时候暂停&quot;，还有一个更贴近实际的问题——<strong>什么时候算测完了？</strong> 这就是退出标准，也是测试计划里最容易被敷衍的一项——&quot;测完就完了&quot;不是标准。一个合格的退出标准至少包含：</p><ul><li><strong>用例通过率</strong>：核心用例 100%，非核心用例 ≥ 95%</li><li><strong>缺陷门禁</strong>：无未修复的 Critical/High 级别 Bug</li><li><strong>覆盖率</strong>：代码覆盖率或需求覆盖率达标（比如需求覆盖率 100%）</li><li><strong>性能指标</strong>：核心接口响应时间在可接受范围内</li></ul><p>退出标准本质上是<strong>测试和质量之间的一份&quot;合同&quot;</strong>——做不到就不算完。如果你不定义退出标准，测试就会陷入&quot;一直测一直有新 bug，不知道什么时候能停&quot;的困境。</p><h3 id="达标了-但心里还是不踏实" tabindex="-1">达标了，但心里还是不踏实 <a class="header-anchor" href="#达标了-但心里还是不踏实" aria-label="Permalink to &quot;达标了，但心里还是不踏实&quot;">​</a></h3><p>比&quot;没有退出标准&quot;更难的是：<strong>标准都达标了，你还是不敢说测完了。</strong></p><p>这种焦虑很常见——因为测试永远无法证明没有 bug，所以你总会觉得&quot;再测测说不定还能发现什么&quot;。但测试的边际效益是递减的：</p><ul><li>前 10 个小时可能发现了 8 个 High 级别 bug</li><li>接下来 10 个小时可能只发现 1 个 Low 级别的拼写问题</li><li>再耗 10 个小时，可能一个都没有</li></ul><p><strong>这时候继续测不是&quot;负责&quot;，是浪费资源。</strong></p><p>一个实用判断信号：<strong>当 Bug 发现率降到稳定低水平时，就是该停的时候。</strong> 比如连续两天每天新增 bug &lt; 2 个且都不是高优先级——这说明软件质量已经进入稳态。继续测下去成本远大于收益。</p><blockquote><p>退出标准是你理性的&quot;合同&quot;，Bug 发现率是你感性的&quot;尺度&quot;。两者都达标了，放手上线，把剩下的测试精力留给下一个迭代。</p></blockquote><h2 id="系统测试怎么测-五维框架" tabindex="-1">系统测试怎么测：五维框架 <a class="header-anchor" href="#系统测试怎么测-五维框架" aria-label="Permalink to &quot;系统测试怎么测：五维框架&quot;">​</a></h2><p>日常说的&quot;测试类型&quot;其实混了好几个维度的概念。比如&quot;回归测试&quot;和&quot;功能测试&quot;不是平级概念——回归回答<strong>为什么测</strong>，功能回答<strong>测什么属性</strong>。附录 <a href="/testing/appendix/test-categories.html">测试分类</a> 将其拆为五个独立维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>回答的问题</th><th>常见成员</th></tr></thead><tbody><tr><td><strong>测试级别</strong></td><td>测多大范围？</td><td>单元测试 → 集成测试 → 系统测试 → 验收测试</td></tr><tr><td><strong>测试类型</strong></td><td>关注什么质量属性？</td><td>功能、性能、安全、兼容性、可用性、可靠性</td></tr><tr><td><strong>测试目的</strong></td><td>这一轮为什么测？</td><td>冒烟测试、回归测试、探索式测试</td></tr><tr><td><strong>测试方法</strong></td><td>怎么看代码？</td><td>黑盒、白盒、灰盒</td></tr><tr><td><strong>执行形态</strong></td><td>人跑还是机器跑？</td><td>静态/动态、手工/自动化</td></tr></tbody></table><blockquote><p>五个维度不是互斥的。比如&quot;用黑盒方法对支付模块做系统级别的回归功能测试&quot;——同时命中方法（黑盒）+ 级别（系统）+ 目的（回归）+ 类型（功能）。一次测试活动 = 五个维度的交叉点。</p></blockquote><p>以下聚焦<strong>系统测试级别</strong>下最常见的七个<strong>测试类型</strong>（即「关注什么质量属性」），覆盖一个软件系统需要验证的核心维度：</p><h3 id="功能测试" tabindex="-1">功能测试 <a class="header-anchor" href="#功能测试" aria-label="Permalink to &quot;功能测试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>验什么</th><th>核心问题</th></tr></thead><tbody><tr><td>需求里的功能有没有正确实现</td><td>&quot;登录能登吗？下单能下吗？支付回调正常吗？&quot;</td></tr></tbody></table><h3 id="性能测试" tabindex="-1">性能测试 <a class="header-anchor" href="#性能测试" aria-label="Permalink to &quot;性能测试&quot;">​</a></h3><p>性能测试按关注点不同有三个递进层次：</p><table tabindex="0"><thead><tr><th>变体</th><th>验什么</th><th>核心问题</th></tr></thead><tbody><tr><td><strong>能力测试</strong></td><td>在&quot;设计要求&quot;负载下表现如何</td><td>&quot;文档说支持 1000 并发，用 1000 跑一轮达标没有？&quot;</td></tr><tr><td><strong>容量测试</strong></td><td>系统能承受的极限在哪</td><td>&quot;一直加压，直到响应时间超标——极限是多少？&quot;</td></tr><tr><td><strong>强度测试</strong></td><td>超负荷时系统的行为</td><td>&quot;并发远超极限后，是优雅降级还是直接崩溃？丢数据吗？&quot;</td></tr></tbody></table><blockquote><p>能力测试测&quot;达标没有&quot;，容量测试测&quot;极限在哪&quot;，强度测试测&quot;超了会怎样&quot;。</p></blockquote><h3 id="安全测试" tabindex="-1">安全测试 <a class="header-anchor" href="#安全测试" aria-label="Permalink to &quot;安全测试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>验什么</th><th>核心问题</th></tr></thead><tbody><tr><td>能不能防住常见攻击</td><td>&quot;SQL 注入、XSS、权限越权——这些基本攻击能防住吗？加密传输？会话管理安全吗？&quot;</td></tr></tbody></table><h3 id="兼容性测试" tabindex="-1">兼容性测试 <a class="header-anchor" href="#兼容性测试" aria-label="Permalink to &quot;兼容性测试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>验什么</th><th>核心问题</th></tr></thead><tbody><tr><td>不同环境能不能正常用</td><td>&quot;Chrome / Safari / Firefox 都 OK 吗？iOS 和 Android 呢？4GB 内存和 16GB 体验差多少？&quot;</td></tr></tbody></table><h3 id="可用性测试" tabindex="-1">可用性测试 <a class="header-anchor" href="#可用性测试" aria-label="Permalink to &quot;可用性测试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>验什么</th><th>核心问题</th></tr></thead><tbody><tr><td>用户能不能轻松完成任务</td><td>&quot;新用户不看帮助文档，能在 30 秒内完成注册吗？错误提示看得懂吗？&quot;</td></tr></tbody></table><h3 id="可靠性测试" tabindex="-1">可靠性测试 <a class="header-anchor" href="#可靠性测试" aria-label="Permalink to &quot;可靠性测试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变体</th><th>验什么</th><th>核心问题</th></tr></thead><tbody><tr><td><strong>可靠性测试</strong></td><td>长时间运行是否稳定</td><td>&quot;连续跑 72 小时，会不会越来越慢或者内存泄漏？&quot;</td></tr><tr><td><strong>可恢复性测试</strong></td><td>出故障后能不能恢复</td><td>&quot;数据库突然宕机，重启后数据完整吗？丢失的请求能补吗？&quot;</td></tr></tbody></table><h3 id="安装-部署测试" tabindex="-1">安装/部署测试 <a class="header-anchor" href="#安装-部署测试" aria-label="Permalink to &quot;安装/部署测试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>验什么</th><th>核心问题</th></tr></thead><tbody><tr><td>安装部署过程是否正常、数据是否正确持久化</td><td>&quot;按部署文档操作，一次能部署成功吗？数据存进去重启后还在不在？&quot;</td></tr></tbody></table><h3 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h3><p>一次迭代不可能把所有测试类型都做全。选择逻辑是：</p><ul><li><strong>每次迭代必做</strong>：功能测试（核心类型）</li><li><strong>每次代码变更后必做</strong>：回归测试（确认改动没搞坏别的 — 这是<strong>测试目的</strong>维度）</li><li><strong>版本发布前必做</strong>：性能测试 + 安全性测试 + 兼容性测试</li><li><strong>大版本/架构变更时必做</strong>：容量测试 + 可恢复性测试</li><li><strong>按行业特性加</strong>：金融加安全合规、医疗加可靠性、面向 C 端加可用性</li></ul><blockquote><p>完整五维框架和详细说明见<a href="/testing/appendix/test-categories.html">附录：测试分类</a>，包括测试级别（单元/集成/系统/验收）、测试目的（冒烟/回归/探索式）、测试方法（黑盒/白盒/灰盒）和执行形态（静态/动态/手工/自动化）。</p></blockquote><h3 id="敏捷中的测试计划-不是一次性的文档" tabindex="-1">敏捷中的测试计划：不是一次性的文档 <a class="header-anchor" href="#敏捷中的测试计划-不是一次性的文档" aria-label="Permalink to &quot;敏捷中的测试计划：不是一次性的文档&quot;">​</a></h3><p>以上测试全流程的写法，容易让你误以为测试是瀑布式的——先做完整计划，然后按计划一步步走。但在敏捷环境中，<strong>测试计划是每个迭代都在做的事。</strong></p><p>在敏捷实践中，测试计划不是一个&quot;写完就归档&quot;的文档。九要素的框架还在，但它们变成了一张每轮迭代都要重新审视的清单：</p><ul><li><strong>范围变了</strong>？——上个迭代加了新功能，这轮测试边界要扩大</li><li><strong>风险变了</strong>？——上周那批重构改动量大，回归策略要加重</li><li><strong>策略要调</strong>？——手工测了三轮已经很稳了，这轮可以加大自动化比例</li></ul><p>测试计划从&quot;一份文档&quot;变成了&quot;一个持续的活动&quot;。每轮迭代启动时花 15 分钟过一遍九要素，比写一份 50 页的测试计划书然后三个月不翻，有效得多。</p><p>顺带一提：<a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>会讲到持续交付中的部署管道——测试的四个阶段（计划→设计→执行→报告）会映射到管道的不同环节，计划阶段对应提交门禁、执行阶段对应验收和容量测试、报告对应发布决策。这里先留个印象。</p><h2 id="测试报告-说清质量到底怎么样" tabindex="-1">测试报告：说清质量到底怎么样 <a class="header-anchor" href="#测试报告-说清质量到底怎么样" aria-label="Permalink to &quot;测试报告：说清质量到底怎么样&quot;">​</a></h2><p>测试的终点不是&quot;测完了&quot;，是<strong>把测试发现的事实讲清楚，让决策者能做判断</strong>。</p><h3 id="报告的六要素" tabindex="-1">报告的六要素 <a class="header-anchor" href="#报告的六要素" aria-label="Permalink to &quot;报告的六要素&quot;">​</a></h3><p>一份完整的测试报告包含 6 个核心要素，按汇报逻辑排列（详见<a href="/testing/appendix/test-report.html">附录：测试报告</a>）：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>要素</th><th>回答的问题</th><th>一句话说明</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>测试概况</strong></td><td>测了什么？谁测的？</td><td>版本、周期、人员、范围一页讲完</td></tr><tr><td style="text-align:center;">2</td><td><strong>测试环境</strong></td><td>在哪测的？</td><td>硬件、软件、工具、数据的完整配置</td></tr><tr><td style="text-align:center;">3</td><td><strong>测试方法</strong></td><td>怎么测的？</td><td>每类测试用什么方法、覆盖到什么程度</td></tr><tr><td style="text-align:center;">4</td><td><strong>缺陷报告</strong></td><td>发现了多少 Bug？</td><td>按严重性和模块统计，找到薄弱环节</td></tr><tr><td style="text-align:center;">5</td><td><strong>测试结果分析</strong></td><td>数据说明了什么？</td><td>用例执行、质量趋势、性能数据、风险与已知问题</td></tr><tr><td style="text-align:center;">6</td><td><strong>结论与建议</strong></td><td>能不能上线？</td><td>三选一结论 + 上线建议</td></tr></tbody></table><blockquote><p>6 个要素按叙述逻辑排列：先交代背景（概况→环境→方法），再展示发现（缺陷→分析），最后给结论。完整模板和示例见<a href="/testing/appendix/test-report.html">附录：测试报告</a>。</p></blockquote><h3 id="测试结论怎么写" tabindex="-1">测试结论怎么写 <a class="header-anchor" href="#测试结论怎么写" aria-label="Permalink to &quot;测试结论怎么写&quot;">​</a></h3><p>结论是报告里最重要的一部分。很多人写到最后，结论就是一句&quot;测试通过&quot;或者&quot;不建议上线&quot;。到底为什么？需要给出量化依据：</p><p><strong>结论必须三选一</strong>（对应附录中的结论格式）：</p><table tabindex="0"><thead><tr><th>结论</th><th>含义</th><th>触发条件</th></tr></thead><tbody><tr><td><strong>✅ 建议上线</strong></td><td>风险可控，可以发布</td><td>P0 全部修复，核心流程通过率 100%，性能达标</td></tr><tr><td><strong>⚠️ 有条件上线</strong></td><td>可以发布，但有限制条件</td><td>有已知问题但不影响大多数用户，或需灰度发布观察</td></tr><tr><td><strong>❌ 不建议上线</strong></td><td>存在无法接受的已知风险</td><td>P0 未修复，核心流程阻塞，性能严重不达标</td></tr></tbody></table><ol><li><strong>覆盖情况</strong>：测了哪些模块、哪些没测到、为什么没测</li><li><strong>缺陷统计</strong>： <ul><li>共发现 X 个 Bug，Critical Y 个、High Z 个</li><li>已修复 a 个、待修复 b 个、暂不修复 c 个及原因</li></ul></li><li><strong>指标达成</strong>：对照测试计划里的退出标准逐项确认</li><li><strong>残留风险</strong>：没覆盖到的区域可能存在什么问题？已知的待修复 Bug 对用户影响多大？</li><li><strong>上线建议</strong>：明确说&quot;可以上线&quot;/&quot;有条件上线（需满足 xxx）&quot;/&quot;不建议上线&quot;</li></ol><blockquote><p><strong>好报告的标准</strong>：不是我写完了，而是<strong>看的人不需要再来问我问题</strong>。</p></blockquote><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>测试工作四阶段：计划（定方向）→ 设计与实现（写用例）→ 执行（找 bug）→ 评估与报告（给结论）</li><li>测试计划遵循 IEEE 829 九要素，其中<strong>暂停/恢复标准</strong>和<strong>退出标准</strong>最容易被敷衍——它们应该是精确量化的门槛，不是&quot;测完就行&quot;</li><li>退出标准达标但心里不踏实时，用 <strong>Bug 发现率</strong>做辅助判断——连续低位运行就是该停的信号，边际效益递减是客观规律</li><li>测试分类不是平铺的，而是五个独立维度（级别/类型/目的/方法/执行形态）；系统测试级别的七种测试类型不用每次都全做，<strong>按风险和里程碑选</strong>：每次迭代必做功能+回归，发布前必做性能+安全+兼容</li><li>能力测试、容量测试、强度测试是性能测试的三个递进层次：达标了没有 → 极限在哪 → 超了会怎样</li><li>在敏捷环境中，测试计划是<strong>每个迭代的持续活动</strong>，IEEE 829 框架不变但每轮重新审视，不是写完就归档的一次性文档</li><li>测试报告遵循六要素结构（概况→环境→方法→缺陷→分析→结论），结论不只是&quot;过还是不过&quot;，要说清<strong>覆盖了什么、发现了什么、还有什么风险、建议怎么做</strong>，且必须三选一：✅ 建议上线 / ⚠️ 有条件上线 / ❌ 不建议上线</li></ol>`,68)])])}const b=r(a,[["render",n]]);export{q as __pageData,b as default};
